"""Value model: types, three-valued logic, comparison and arithmetic."""

from __future__ import annotations

from .errors import TypeMismatchError

TYPE_NAMES = ("INT", "FLOAT", "TEXT", "BOOL")


def type_of(v: object) -> str:
    """Return the microdb type name of a Python value."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    """True for int and float values, never for bool or None."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _check_logical(v: object) -> None:
    if v is not None and not isinstance(v, bool):
        raise TypeMismatchError(f"expected a BOOL value, got {type_of(v)}")


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND."""
    _check_logical(a)
    _check_logical(b)
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR."""
    _check_logical(a)
    _check_logical(b)
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT."""
    _check_logical(a)
    if a is None:
        return None
    return not a


def require_logical(v: object) -> bool | None:
    """Return v if it is a logical value, else raise TypeMismatchError."""
    _check_logical(v)
    return v  # type: ignore[return-value]


def _check_comparable(a: object, b: object) -> None:
    if is_numeric(a) and is_numeric(b):
        return
    if isinstance(a, str) and isinstance(b, str):
        return
    if isinstance(a, bool) and isinstance(b, bool):
        return
    raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def compare_eq(a: object, b: object) -> bool | None:
    """SQL equality: UNKNOWN when either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """SQL less-than: UNKNOWN when either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b  # type: ignore[operator]


def compare(op: str, a: object, b: object) -> bool | None:
    """Evaluate any comparison operator (= <> < <= > >=)."""
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        return not_(compare_eq(a, b))
    if op == "<":
        return compare_lt(a, b)
    if op == ">":
        return compare_lt(b, a)
    if op == "<=":
        return or_(compare_lt(a, b), compare_eq(a, b))
    if op == ">=":
        return or_(compare_lt(b, a), compare_eq(a, b))
    raise ValueError(f"unknown comparison operator {op!r}")


def arith(op: str, a: object, b: object) -> object:
    """Evaluate a binary arithmetic operator (+ - * / %)."""
    if a is None or b is None:
        return None
    if not (is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError(
            f"operator {op} requires numeric operands, got {type_of(a)} and {type_of(b)}"
        )
    if op == "+":
        return a + b  # type: ignore[operator]
    if op == "-":
        return a - b  # type: ignore[operator]
    if op == "*":
        return a * b  # type: ignore[operator]
    if op == "/":
        if b == 0:
            return None
        return float(a) / float(b)  # type: ignore[arg-type]
    if op == "%":
        if not (type(a) is int and type(b) is int):
            raise TypeMismatchError("operator % requires INT operands")
        if b == 0:
            return None
        return a % b
    raise ValueError(f"unknown arithmetic operator {op!r}")


def negate(a: object) -> object:
    """Unary minus; preserves the numeric type, NULL propagates."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a  # type: ignore[operator]


def group_key(v: object) -> tuple:
    """Hashable key where NULL equals NULL and BOOL never equals a number."""
    if v is None:
        return ("NULL",)
    if isinstance(v, bool):
        return ("BOOL", v)
    if is_numeric(v):
        return ("NUM", v)
    return ("TEXT", v)


def row_key(values: list[object]) -> tuple:
    """Hashable key of a whole row for grouping and DISTINCT."""
    return tuple(group_key(v) for v in values)

"""Schema layer: Column and Table."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError
from .value import TYPE_NAMES, type_of


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str  # "INT" | "FLOAT" | "TEXT" | "BOOL"


def _coerce_cell(column: Column, cell: object) -> object:
    if cell is None:
        return None
    kind = type_of(cell) if isinstance(cell, (bool, int, float, str)) else "?"
    if kind == column.type:
        return cell
    if column.type == "FLOAT" and kind == "INT":
        return float(cell)  # type: ignore[arg-type]
    raise SchemaError(
        f"column {column.name!r} of type {column.type} cannot hold {cell!r}"
    )


class Table:
    """An immutable-schema, in-memory table."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        columns = list(columns)
        if not columns:
            raise SchemaError(f"table {name!r} has no columns")
        seen: set[str] = set()
        for col in columns:
            if col.type not in TYPE_NAMES:
                raise SchemaError(f"column {col.name!r} has unknown type {col.type!r}")
            if col.name in seen:
                raise SchemaError(f"duplicate column name {col.name!r}")
            seen.add(col.name)
        checked: list[list[object]] = []
        for number, row in enumerate(rows):
            row = list(row)
            if len(row) != len(columns):
                raise SchemaError(
                    f"row {number} has {len(row)} values, expected {len(columns)}"
                )
            checked.append([_coerce_cell(c, v) for c, v in zip(columns, row)])
        self._name = name
        self._columns = columns
        self._rows = checked
        self._index = {c.name: i for i, c in enumerate(columns)}

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return [list(r) for r in self._rows]

    def column_index(self, name: str) -> int:
        """Return the position of a column; SchemaError if it does not exist."""
        try:
            return self._index[name]
        except KeyError:
            raise SchemaError(f"table {self._name!r} has no column {name!r}") from None

    def __repr__(self) -> str:
        return f"Table({self._name!r}, {self._columns!r}, <{len(self._rows)} rows>)"

"""Lexer: turns query text into a list of tokens."""

from __future__ import annotations

import dataclasses

from .errors import LexError

KEYWORDS = frozenset(
    "SELECT DISTINCT FROM INNER LEFT JOIN ON WHERE GROUP BY HAVING ORDER ASC DESC "
    "LIMIT OFFSET AS AND OR NOT IS NULL TRUE FALSE".split()
)

_TWO_CHAR_OPS = ("<>", "<=", ">=")
_ONE_CHAR_OPS = "=<>+-*/%(),."


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str  # "INT" | "FLOAT" | "TEXT" | "IDENT" | "KEYWORD" | "OP" | "EOF"
    value: object
    offset: int
    end: int


def _is_ident_start(c: str) -> bool:
    return c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z")


def _is_ident_char(c: str) -> bool:
    return _is_ident_start(c) or c.isdigit() and c.isascii()


def _is_digit(c: str) -> bool:
    return "0" <= c <= "9"


def _digits_end(text: str, i: int) -> int:
    while i < len(text) and _is_digit(text[i]):
        i += 1
    return i


def _lex_number(text: str, start: int) -> Token:
    i = _digits_end(text, start)
    is_float = False
    if i < len(text) and text[i] == ".":
        is_float = True
        i = _digits_end(text, i + 1)
    if i < len(text) and text[i] in "eE":
        j = i + 1
        if j < len(text) and text[j] in "+-":
            j += 1
        if j < len(text) and _is_digit(text[j]):
            is_float = True
            i = _digits_end(text, j)
    raw = text[start:i]
    if is_float:
        return Token("FLOAT", float(raw), start, i)
    return Token("INT", int(raw), start, i)


def _lex_text(text: str, start: int) -> Token:
    i = start + 1
    parts: list[str] = []
    while True:
        j = text.find("'", i)
        if j < 0:
            raise LexError("unterminated text literal", start)
        parts.append(text[i:j])
        if j + 1 < len(text) and text[j + 1] == "'":
            parts.append("'")
            i = j + 2
            continue
        return Token("TEXT", "".join(parts), start, j + 1)


def _lex_word(text: str, start: int) -> Token:
    i = start
    while i < len(text) and _is_ident_char(text[i]):
        i += 1
    word = text[start:i]
    if word.upper() in KEYWORDS:
        return Token("KEYWORD", word.upper(), start, i)
    return Token("IDENT", word, start, i)


def _skip_space(text: str, i: int) -> int:
    while i < len(text):
        c = text[i]
        if c.isspace():
            i += 1
        elif text.startswith("--", i):
            nl = text.find("\n", i)
            i = len(text) if nl < 0 else nl + 1
        else:
            break
    return i


def _next_token(text: str, i: int) -> Token:
    c = text[i]
    if _is_digit(c) or (c == "." and i + 1 < len(text) and _is_digit(text[i + 1])):
        return _lex_number(text, i)
    if c == "'":
        return _lex_text(text, i)
    if _is_ident_start(c):
        return _lex_word(text, i)
    two = text[i : i + 2]
    if two in _TWO_CHAR_OPS:
        return Token("OP", two, i, i + 2)
    if c in _ONE_CHAR_OPS:
        return Token("OP", c, i, i + 1)
    raise LexError(f"unexpected character {c!r}", i)


def tokenize(text: str) -> list[Token]:
    """Tokenize query text; the result always ends with an EOF token."""
    tokens: list[Token] = []
    i = _skip_space(text, 0)
    while i < len(text):
        tok = _next_token(text, i)
        tokens.append(tok)
        i = _skip_space(text, tok.end)
    tokens.append(Token("EOF", None, len(text), len(text)))
    return tokens

"""Recursive-descent parser producing a Query AST."""

from __future__ import annotations

import dataclasses

from .aggregate import AGGREGATE_NAMES
from .errors import ParseError
from .lexer import Token, tokenize

# ---------------------------------------------------------------- AST nodes


class Expr:
    """Base class of expression nodes."""


@dataclasses.dataclass(frozen=True)
class Literal(Expr):
    value: object
    kind: str  # included so that Literal(1) != Literal(True) != Literal(1.0)


@dataclasses.dataclass(frozen=True)
class ColumnRef(Expr):
    table: str | None
    name: str


@dataclasses.dataclass(frozen=True)
class UnaryMinus(Expr):
    operand: Expr


@dataclasses.dataclass(frozen=True)
class Not(Expr):
    operand: Expr


@dataclasses.dataclass(frozen=True)
class BinaryOp(Expr):
    op: str  # + - * / % = <> < <= > >= AND OR
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class IsNull(Expr):
    operand: Expr
    negated: bool


@dataclasses.dataclass(frozen=True)
class FuncCall(Expr):
    name: str  # lower case
    args: tuple


@dataclasses.dataclass(frozen=True)
class AggCall(Expr):
    name: str  # lower case
    args: tuple
    star: bool  # count(*)


@dataclasses.dataclass(frozen=True)
class SelectItem:
    expr: Expr | None  # None for star items
    alias: str | None
    star: bool
    star_table: str | None
    text: str  # source text, whitespace collapsed


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str  # "INNER" | "LEFT"
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    items: tuple
    table: str
    join: JoinClause | None
    where: Expr | None
    group_by: tuple
    having: Expr | None
    order_by: tuple
    limit: int | None
    offset: int | None


_COMPARISONS = ("=", "<>", "<", "<=", ">", ">=")


# ---------------------------------------------------------------- parser


class _Parser:
    def __init__(self, text: str) -> None:
        self.text = text
        self.tokens = tokenize(text)
        self.pos = 0
        self.in_aggregate = False

    # -- token helpers
    @property
    def tok(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "EOF":
            self.pos += 1
        return tok

    def error(self, message: str, tok: Token | None = None) -> ParseError:
        tok = tok or self.tok
        found = "end of input" if tok.kind == "EOF" else repr(self.text[tok.offset : tok.end])
        return ParseError(f"{message}, found {found}", tok.offset)

    def is_kw(self, *words: str) -> bool:
        return self.tok.kind == "KEYWORD" and self.tok.value in words

    def is_op(self, *ops: str) -> bool:
        return self.tok.kind == "OP" and self.tok.value in ops

    def accept_kw(self, word: str) -> bool:
        if self.is_kw(word):
            self.advance()
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.is_op(op):
            self.advance()
            return True
        return False

    def expect_kw(self, word: str) -> Token:
        if not self.is_kw(word):
            raise self.error(f"expected {word}")
        return self.advance()

    def expect_op(self, op: str) -> Token:
        if not self.is_op(op):
            raise self.error(f"expected {op!r}")
        return self.advance()

    def expect_ident(self, what: str) -> str:
        if self.tok.kind != "IDENT":
            raise self.error(f"expected {what}")
        return str(self.advance().value)

    def expect_int(self, what: str) -> int:
        if self.tok.kind != "INT":
            raise self.error(f"expected an integer after {what}")
        return int(self.advance().value)  # type: ignore[arg-type]

    # -- query
    def parse_query(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")
        items = self.parse_list(self.parse_select_item)
        self.expect_kw("FROM")
        table = self.expect_ident("a table name")
        join = self.parse_join()
        where = self.parse_expr() if self.accept_kw("WHERE") else None
        group_by: list = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by = self.parse_list(self.parse_expr)
        having = self.parse_expr() if self.accept_kw("HAVING") else None
        order_by: list = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by = self.parse_list(self.parse_order_item)
        limit = self.expect_int("LIMIT") if self.accept_kw("LIMIT") else None
        offset = self.expect_int("OFFSET") if self.accept_kw("OFFSET") else None
        if self.tok.kind != "EOF":
            raise self.error("unexpected token")
        return Query(distinct, tuple(items), table, join, where, tuple(group_by),
                     having, tuple(order_by), limit, offset)

    def parse_list(self, parse_one):  # type: ignore[no-untyped-def]
        items = [parse_one()]
        while self.accept_op(","):
            items.append(parse_one())
        return items

    def parse_join(self) -> JoinClause | None:
        kind = "INNER"
        if self.accept_kw("LEFT"):
            kind = "LEFT"
        elif not self.accept_kw("INNER") and not self.is_kw("JOIN"):
            return None
        self.expect_kw("JOIN")
        table = self.expect_ident("a table name")
        self.expect_kw("ON")
        return JoinClause(kind, table, self.parse_expr())

    def parse_select_item(self) -> SelectItem:
        start = self.tok
        if self.accept_op("*"):
            return SelectItem(None, None, True, None, "*")
        nxt = self.tokens[self.pos + 1 : self.pos + 3]
        if (start.kind == "IDENT" and len(nxt) == 2 and nxt[0].value == "."
                and nxt[0].kind == "OP" and nxt[1].kind == "OP" and nxt[1].value == "*"):
            self.pos += 3
            return SelectItem(None, None, True, str(start.value), f"{start.value}.*")
        expr = self.parse_expr()
        end = self.tokens[self.pos - 1].end
        text = " ".join(self.text[start.offset : end].split())
        alias = self.expect_ident("an alias after AS") if self.accept_kw("AS") else None
        return SelectItem(expr, alias, False, None, text)

    def parse_order_item(self) -> OrderItem:
        expr = self.parse_expr()
        if self.accept_kw("DESC"):
            return OrderItem(expr, True)
        self.accept_kw("ASC")
        return OrderItem(expr, False)

    # -- expressions
    def parse_expr(self) -> Expr:
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = BinaryOp("OR", left, self.parse_and())
        return left

    def parse_and(self) -> Expr:
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = BinaryOp("AND", left, self.parse_not())
        return left

    def parse_not(self) -> Expr:
        if self.accept_kw("NOT"):
            return Not(self.parse_not())
        return self.parse_predicate()

    def parse_predicate(self) -> Expr:
        left = self.parse_additive()
        if self.is_op(*_COMPARISONS):
            op = str(self.advance().value)
            left = BinaryOp(op, left, self.parse_additive())
        elif self.accept_kw("IS"):
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            left = IsNull(left, negated)
        else:
            return left
        if self.is_op(*_COMPARISONS) or self.is_kw("IS"):
            raise self.error("comparison operators are not associative")
        return left

    def parse_additive(self) -> Expr:
        left = self.parse_multiplicative()
        while self.is_op("+", "-"):
            op = str(self.advance().value)
            left = BinaryOp(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self) -> Expr:
        left = self.parse_unary()
        while self.is_op("*", "/", "%"):
            op = str(self.advance().value)
            left = BinaryOp(op, left, self.parse_unary())
        return left

    def parse_unary(self) -> Expr:
        if self.accept_op("-"):
            return UnaryMinus(self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        tok = self.tok
        if tok.kind in ("INT", "FLOAT", "TEXT"):
            self.advance()
            return Literal(tok.value, tok.kind)
        if tok.kind == "KEYWORD" and tok.value in ("TRUE", "FALSE", "NULL"):
            self.advance()
            if tok.value == "NULL":
                return Literal(None, "NULL")
            return Literal(tok.value == "TRUE", "BOOL")
        if tok.kind == "IDENT":
            return self.parse_identifier()
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        raise self.error("expected an expression")

    def parse_identifier(self) -> Expr:
        tok = self.advance()
        name = str(tok.value)
        if self.accept_op("("):
            return self.parse_call(tok)
        if self.accept_op("."):
            column = self.expect_ident("a column name after '.'")
            return ColumnRef(name, column)
        return ColumnRef(None, name)

    def parse_call(self, name_tok: Token) -> Expr:
        name = str(name_tok.value).lower()
        is_agg = name in AGGREGATE_NAMES
        if is_agg and self.in_aggregate:
            raise ParseError(f"aggregate {name}() may not be nested", name_tok.offset)
        if self.is_op("*"):
            if name != "count":
                raise self.error(f"'*' is only allowed in count(*), not {name}()")
            self.advance()
            self.expect_op(")")
            return AggCall(name, (), True)
        saved = self.in_aggregate
        self.in_aggregate = saved or is_agg
        try:
            args = [] if self.is_op(")") else self.parse_list(self.parse_expr)
        finally:
            self.in_aggregate = saved
        self.expect_op(")")
        if is_agg:
            return AggCall(name, tuple(args), False)
        return FuncCall(name, tuple(args))


def parse(text: str) -> Query:
    """Parse a query string into a Query."""
    return _Parser(text).parse_query()

"""Aggregate functions: count, sum, avg, min, max."""

from __future__ import annotations

from .errors import TypeMismatchError
from .value import compare_lt, is_numeric, type_of

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})


def is_aggregate(name: str) -> bool:
    """True when name (any case) is an aggregate function."""
    return name.lower() in AGGREGATE_NAMES


def _non_null(values: list[object]) -> list[object]:
    return [v for v in values if v is not None]


def _require_numeric(name: str, values: list[object]) -> None:
    for v in values:
        if not is_numeric(v):
            raise TypeMismatchError(f"{name}() requires numeric input, got {type_of(v)}")


def agg_count_star(row_count: int) -> int:
    """count(*): the number of rows, NULL or not."""
    return row_count


def agg_count(values: list[object]) -> int:
    """count(expr): the number of non-NULL values."""
    return len(_non_null(values))


def agg_sum(values: list[object]) -> object:
    """Sum of non-NULL values; NULL when there are none; INT only if all INT."""
    present = _non_null(values)
    _require_numeric("sum", present)
    if not present:
        return None
    total: int | float = 0
    for v in present:
        total = total + v  # type: ignore[operator]
    if any(isinstance(v, float) for v in present):
        return float(total)
    return total


def agg_avg(values: list[object]) -> float | None:
    """Mean of non-NULL values as FLOAT; NULL when there are none."""
    present = _non_null(values)
    _require_numeric("avg", present)
    if not present:
        return None
    total: int | float = 0
    for v in present:
        total = total + v  # type: ignore[operator]
    return float(total / len(present))


def _extreme(values: list[object], want_min: bool) -> object:
    best: object = None
    for v in _non_null(values):
        if best is None:
            compare_lt(v, v)  # validates the value is orderable
            best = v
        elif compare_lt(v, best) if want_min else compare_lt(best, v):
            best = v
    return best


def agg_min(values: list[object]) -> object:
    """Smallest non-NULL value, type preserved; NULL when there are none."""
    return _extreme(values, True)


def agg_max(values: list[object]) -> object:
    """Largest non-NULL value, type preserved; NULL when there are none."""
    return _extreme(values, False)


_FUNCTIONS = {
    "count": agg_count,
    "sum": agg_sum,
    "avg": agg_avg,
    "min": agg_min,
    "max": agg_max,
}


def compute_aggregate(name: str, values: list[object]) -> object:
    """Apply the named aggregate to a list of input values."""
    return _FUNCTIONS[name.lower()](values)

"""Expression binding (name resolution) and evaluation."""

from __future__ import annotations

import dataclasses
from typing import Callable

from .errors import (
    AggregateError,
    AmbiguousColumnError,
    ArityError,
    MicroDBError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from .parser import (
    AggCall,
    BinaryOp,
    ColumnRef,
    Expr,
    FuncCall,
    IsNull,
    Literal,
    Not,
    UnaryMinus,
)
from .value import and_, arith, compare, is_numeric, negate, not_, or_, type_of

# ---------------------------------------------------------------- bound nodes


@dataclasses.dataclass(frozen=True)
class BoundColumn(Expr):
    """A resolved reference to a position in the working row."""

    index: int
    name: str = dataclasses.field(default="", compare=False)


@dataclasses.dataclass(frozen=True)
class OutputColumn(Expr):
    """A reference to a position in the projected output row (ORDER BY)."""

    index: int


@dataclasses.dataclass(frozen=True)
class GroupKey(Expr):
    """A reference to a component of the current group's key."""

    index: int


@dataclasses.dataclass(frozen=True)
class AggRef(Expr):
    """A reference to a precomputed aggregate value of the current group."""

    index: int


@dataclasses.dataclass
class Context:
    """Evaluation context; each field is only needed by some node kinds."""

    row: list | None = None
    out: list | None = None
    keys: list | None = None
    aggs: list | None = None


# ---------------------------------------------------------------- scope


class Scope:
    """The columns visible to an expression: (table name, column name) pairs."""

    def __init__(self, entries: list[tuple[str, str]], tables: list[str]) -> None:
        self.entries = list(entries)
        self.tables = list(tables)

    def resolve(self, table: str | None, name: str) -> int:
        """Return the working-row index of a column reference."""
        if table is not None and table not in self.tables:
            raise UnknownTableError(f"unknown table {table!r}")
        matches = [
            i for i, (t, c) in enumerate(self.entries)
            if c == name and (table is None or t == table)
        ]
        label = name if table is None else f"{table}.{name}"
        if not matches:
            raise UnknownColumnError(f"unknown column {label!r}")
        if len(matches) > 1:
            raise AmbiguousColumnError(f"column reference {label!r} is ambiguous")
        return matches[0]


# ---------------------------------------------------------------- tree helpers


def map_children(node: Expr, fn: Callable[[Expr], Expr]) -> Expr:
    """Return node with fn applied to each direct child expression."""
    if isinstance(node, (UnaryMinus, Not, IsNull)):
        return dataclasses.replace(node, operand=fn(node.operand))
    if isinstance(node, BinaryOp):
        return dataclasses.replace(node, left=fn(node.left), right=fn(node.right))
    if isinstance(node, (FuncCall, AggCall)):
        return dataclasses.replace(node, args=tuple(fn(a) for a in node.args))
    return node


def contains_aggregate(node: Expr | None) -> bool:
    """True when an aggregate call appears anywhere inside node."""
    if node is None:
        return False
    if isinstance(node, AggCall):
        return True
    found = []

    def visit(child: Expr) -> Expr:
        found.append(contains_aggregate(child))
        return child

    map_children(node, visit)
    return any(found)


# ---------------------------------------------------------------- functions


def _text_args(name: str, args: list[object]) -> None:
    for a in args:
        if a is not None and not isinstance(a, str):
            raise TypeMismatchError(f"{name}() requires TEXT, got {type_of(a)}")


def _fn_concat(args: list[object]) -> object:
    _text_args("concat", args)
    if any(a is None for a in args):
        return None
    return "".join(args)  # type: ignore[arg-type]


def _fn_upper(args: list[object]) -> object:
    _text_args("upper", args)
    return None if args[0] is None else args[0].upper()  # type: ignore[union-attr]


def _fn_lower(args: list[object]) -> object:
    _text_args("lower", args)
    return None if args[0] is None else args[0].lower()  # type: ignore[union-attr]


def _fn_length(args: list[object]) -> object:
    _text_args("length", args)
    return None if args[0] is None else len(args[0])  # type: ignore[arg-type]


def _fn_abs(args: list[object]) -> object:
    v = args[0]
    if v is None:
        return None
    if not is_numeric(v):
        raise TypeMismatchError(f"abs() requires a number, got {type_of(v)}")
    return abs(v)  # type: ignore[arg-type]


def _fn_coalesce(args: list[object]) -> object:
    for a in args:
        if a is not None:
            return a
    return None


# name -> (minimum arity, maximum arity or None, implementation)
FUNCTIONS: dict[str, tuple[int, int | None, Callable[[list[object]], object]]] = {
    "concat": (2, None, _fn_concat),
    "upper": (1, 1, _fn_upper),
    "lower": (1, 1, _fn_lower),
    "length": (1, 1, _fn_length),
    "abs": (1, 1, _fn_abs),
    "coalesce": (1, None, _fn_coalesce),
}


def _arity_message(name: str, low: int, high: int | None, got: int) -> str:
    if high is None:
        expected = f"at least {low}"
    elif low == high:
        expected = f"exactly {low}"
    else:
        expected = f"{low} to {high}"
    return f"function {name}() expects {expected} argument(s), got {got}"


def check_function(name: str, argc: int) -> None:
    """Validate that a scalar function exists and accepts argc arguments."""
    spec = FUNCTIONS.get(name.lower())
    if spec is None:
        raise UnknownFunctionError(f"unknown function {name!r}")
    low, high, _ = spec
    if argc < low or (high is not None and argc > high):
        raise ArityError(_arity_message(name, low, high, argc))


def check_aggregate(node: AggCall) -> None:
    """Validate the arity of an aggregate call."""
    if node.star:
        return
    if len(node.args) != 1:
        raise ArityError(_arity_message(node.name, 1, 1, len(node.args)))


def call_function(name: str, args: list[object]) -> object:
    """Invoke a scalar function on already-evaluated arguments."""
    check_function(name, len(args))
    return FUNCTIONS[name.lower()][2](args)


# ---------------------------------------------------------------- binding


def bind(node: Expr, scope: Scope, allow_aggregates: bool = False, clause: str = "") -> Expr:
    """Resolve column references to positions and validate calls.

    Aggregates are rejected with AggregateError unless allow_aggregates is set.
    """
    if isinstance(node, ColumnRef):
        return BoundColumn(scope.resolve(node.table, node.name), node.name)
    if isinstance(node, FuncCall):
        check_function(node.name, len(node.args))
    if isinstance(node, AggCall):
        if not allow_aggregates:
            where = f" in {clause}" if clause else " here"
            raise AggregateError(f"aggregate {node.name}() is not allowed{where}")
        check_aggregate(node)
        return map_children(node, lambda c: bind(c, scope, False, "an aggregate argument"))
    return map_children(node, lambda c: bind(c, scope, allow_aggregates, clause))


# ---------------------------------------------------------------- evaluation


def _eval_binary(node: BinaryOp, ctx: Context) -> object:
    left = evaluate(node.left, ctx)
    right = evaluate(node.right, ctx)
    op = node.op
    if op == "AND":
        return and_(left, right)  # type: ignore[arg-type]
    if op == "OR":
        return or_(left, right)  # type: ignore[arg-type]
    if op in "+-*/%":
        return arith(op, left, right)
    return compare(op, left, right)


def evaluate(node: Expr, ctx: Context) -> object:
    """Evaluate a bound expression in the given context."""
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, BoundColumn):
        return ctx.row[node.index]  # type: ignore[index]
    if isinstance(node, OutputColumn):
        return ctx.out[node.index]  # type: ignore[index]
    if isinstance(node, GroupKey):
        return ctx.keys[node.index]  # type: ignore[index]
    if isinstance(node, AggRef):
        return ctx.aggs[node.index]  # type: ignore[index]
    if isinstance(node, BinaryOp):
        return _eval_binary(node, ctx)
    if isinstance(node, UnaryMinus):
        return negate(evaluate(node.operand, ctx))
    if isinstance(node, Not):
        return not_(evaluate(node.operand, ctx))  # type: ignore[arg-type]
    if isinstance(node, IsNull):
        return (evaluate(node.operand, ctx) is None) != node.negated
    if isinstance(node, FuncCall):
        return call_function(node.name, [evaluate(a, ctx) for a in node.args])
    if isinstance(node, AggCall):
        raise MicroDBError(f"aggregate {node.name}() evaluated outside a group")
    raise MicroDBError(f"cannot evaluate unbound expression {node!r}")

"""Planner: turns a Query into an inspectable pipeline of named stages."""

from __future__ import annotations

import dataclasses
from collections.abc import Sequence
from typing import Iterator, overload

from .errors import AggregateError
from .expr import contains_aggregate
from .parser import Expr, JoinClause, OrderItem, Query, SelectItem


@dataclasses.dataclass(frozen=True)
class Stage:
    """Base class of plan stages; every stage has a ``name``."""

    @property
    def name(self) -> str:
        return "stage"


@dataclasses.dataclass(frozen=True)
class ScanStage(Stage):
    table: str

    @property
    def name(self) -> str:
        return "scan"


@dataclasses.dataclass(frozen=True)
class JoinStage(Stage):
    kind: str
    table: str
    on: Expr

    @property
    def name(self) -> str:
        return "join"


@dataclasses.dataclass(frozen=True)
class FilterStage(Stage):
    predicate: Expr

    @property
    def name(self) -> str:
        return "filter"


@dataclasses.dataclass(frozen=True)
class GroupStage(Stage):
    keys: tuple  # empty for the implicit whole-input group

    @property
    def name(self) -> str:
        return "group"


@dataclasses.dataclass(frozen=True)
class AggregateStage(Stage):
    @property
    def name(self) -> str:
        return "aggregate"


@dataclasses.dataclass(frozen=True)
class HavingStage(Stage):
    predicate: Expr

    @property
    def name(self) -> str:
        return "having"


@dataclasses.dataclass(frozen=True)
class ProjectStage(Stage):
    items: tuple

    @property
    def name(self) -> str:
        return "project"


@dataclasses.dataclass(frozen=True)
class DistinctStage(Stage):
    @property
    def name(self) -> str:
        return "distinct"


@dataclasses.dataclass(frozen=True)
class SortStage(Stage):
    keys: tuple  # of OrderItem

    @property
    def name(self) -> str:
        return "sort"


@dataclasses.dataclass(frozen=True)
class OffsetStage(Stage):
    count: int

    @property
    def name(self) -> str:
        return "offset"


@dataclasses.dataclass(frozen=True)
class LimitStage(Stage):
    count: int

    @property
    def name(self) -> str:
        return "limit"


class Plan(Sequence):
    """An ordered, immutable sequence of stages, plus the source query."""

    def __init__(self, stages: list[Stage], query: Query) -> None:
        self._stages = tuple(stages)
        self.query = query

    @overload
    def __getitem__(self, index: int) -> Stage: ...

    @overload
    def __getitem__(self, index: slice) -> tuple: ...

    def __getitem__(self, index: int | slice) -> Stage | tuple:
        return self._stages[index]

    def __len__(self) -> int:
        return len(self._stages)

    def __iter__(self) -> Iterator[Stage]:
        return iter(self._stages)

    @property
    def names(self) -> list[str]:
        return [s.name for s in self._stages]

    def find(self, stage_type: type) -> Stage | None:
        """Return the first stage of the given type, or None."""
        for stage in self._stages:
            if isinstance(stage, stage_type):
                return stage
        return None

    def __repr__(self) -> str:
        return f"Plan({' -> '.join(self.names)})"


def _is_grouped(query: Query) -> bool:
    # HAVING without GROUP BY makes the whole input one group, as in standard SQL.
    if query.group_by or query.having is not None:
        return True
    return any(contains_aggregate(item.expr) for item in query.items)


def _validate(query: Query) -> None:
    if query.join is not None and contains_aggregate(query.join.on):
        raise AggregateError("aggregates are not allowed in JOIN ... ON")
    if contains_aggregate(query.where):
        raise AggregateError("aggregates are not allowed in WHERE")
    if any(contains_aggregate(k) for k in query.group_by):
        raise AggregateError("aggregates are not allowed in GROUP BY")
    if not _is_grouped(query):
        if any(contains_aggregate(o.expr) for o in query.order_by):
            raise AggregateError("aggregates in ORDER BY require grouping")


def plan(query: Query) -> Plan:
    """Build the execution pipeline for a parsed query."""
    _validate(query)
    stages: list[Stage] = [ScanStage(query.table)]
    join: JoinClause | None = query.join
    if join is not None:
        stages.append(JoinStage(join.kind, join.table, join.on))
    if query.where is not None:
        stages.append(FilterStage(query.where))
    if _is_grouped(query):
        stages.append(GroupStage(tuple(query.group_by)))
        stages.append(AggregateStage())
        if query.having is not None:
            stages.append(HavingStage(query.having))
    items: tuple[SelectItem, ...] = query.items
    stages.append(ProjectStage(items))
    if query.distinct:
        stages.append(DistinctStage())
    if query.order_by:
        order: tuple[OrderItem, ...] = query.order_by
        stages.append(SortStage(order))
    if query.offset is not None:
        stages.append(OffsetStage(query.offset))
    if query.limit is not None:
        stages.append(LimitStage(query.limit))
    return Plan(stages, query)

"""Executor: runs a Plan against a set of tables."""

from __future__ import annotations

import dataclasses
import functools
from typing import Callable

from .aggregate import agg_count_star, compute_aggregate
from .errors import GroupingError, UnknownTableError
from .expr import (
    AggRef,
    BoundColumn,
    Context,
    GroupKey,
    OutputColumn,
    Scope,
    bind,
    evaluate,
    map_children,
)
from .parser import AggCall, ColumnRef, Expr, SelectItem, parse
from .planner import (
    AggregateStage,
    DistinctStage,
    FilterStage,
    GroupStage,
    HavingStage,
    JoinStage,
    LimitStage,
    OffsetStage,
    Plan,
    ProjectStage,
    ScanStage,
    SortStage,
    Stage,
    plan,
)
from .schema import Table
from .value import compare_eq, compare_lt, require_logical, row_key


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


@dataclasses.dataclass
class _Group:
    keys: list
    rows: list
    aggs: list = dataclasses.field(default_factory=list)


@dataclasses.dataclass
class _State:
    plan: Plan
    tables: dict[str, Table]
    scope: Scope = dataclasses.field(default_factory=lambda: Scope([], []))
    rows: list = dataclasses.field(default_factory=list)
    prepared: bool = False
    grouped: bool = False
    where: Expr | None = None
    keys: list = dataclasses.field(default_factory=list)
    aggs: list = dataclasses.field(default_factory=list)
    items: list = dataclasses.field(default_factory=list)
    sources: list = dataclasses.field(default_factory=list)
    columns: list = dataclasses.field(default_factory=list)
    having: Expr | None = None
    order: list = dataclasses.field(default_factory=list)
    groups: list = dataclasses.field(default_factory=list)
    outputs: list = dataclasses.field(default_factory=list)


def _is_true(value: object) -> bool:
    return require_logical(value) is True


def _lookup_table(state: _State, name: str) -> Table:
    table = state.tables.get(name)
    if table is None:
        raise UnknownTableError(f"unknown table {name!r}")
    return table


# ---------------------------------------------------------------- preparation


def output_name(item: SelectItem) -> str:
    """Alias, else the column name of a column reference, else the source text."""
    if item.alias is not None:
        return item.alias
    # A qualified reference t.c is also named after its column, c.
    if isinstance(item.expr, ColumnRef):
        return item.expr.name
    return item.text


def _group_compile(node: Expr, state: _State) -> Expr:
    """Rewrite a bound expression so that it evaluates against a group."""
    for i, key in enumerate(state.keys):
        if node == key:
            return GroupKey(i)
    if isinstance(node, AggCall):
        if node not in state.aggs:
            state.aggs.append(node)
        return AggRef(state.aggs.index(node))
    if isinstance(node, BoundColumn):
        raise GroupingError(
            f"column {node.name!r} must appear in GROUP BY or be used in an aggregate"
        )
    return map_children(node, lambda c: _group_compile(c, state))


def _finish(node: Expr, state: _State, scope: Scope, clause: str, aggs: bool) -> Expr:
    bound = bind(node, scope, aggs and state.grouped, clause)
    return _group_compile(bound, state) if state.grouped else bound


def _expand_star(item: SelectItem, state: _State) -> None:
    scope = state.scope
    if item.star_table is not None and item.star_table not in scope.tables:
        raise UnknownTableError(f"unknown table {item.star_table!r}")
    for i, (table, column) in enumerate(scope.entries):
        if item.star_table is None or table == item.star_table:
            state.items.append(_finish(BoundColumn(i, column), state, scope, "SELECT", False))
            state.columns.append(column)
            state.sources.append(ColumnRef(table, column))


def _prepare_items(state: _State, items: tuple) -> None:
    for item in items:
        if item.star:
            _expand_star(item, state)
            continue
        state.items.append(_finish(item.expr, state, state.scope, "SELECT", True))
        state.columns.append(output_name(item))
        state.sources.append(item.expr)


def _resolve_outputs(node: Expr, state: _State) -> Expr:
    """Replace ORDER BY references to output columns; an alias beats an input column."""
    if isinstance(node, ColumnRef) and node.table is None and node.name in state.columns:
        return OutputColumn(state.columns.index(node.name))
    for i, source in enumerate(state.sources):
        if node == source:
            return OutputColumn(i)
    return map_children(node, lambda c: _resolve_outputs(c, state))


def _prepare_order(state: _State, stage: SortStage) -> None:
    distinct = state.plan.find(DistinctStage) is not None
    # After DISTINCT only output columns exist; any other column reference is
    # reported as UnknownColumnError (and aggregates as AggregateError).
    scope = Scope([], state.scope.tables) if distinct else state.scope
    for item in stage.keys:
        node = _resolve_outputs(item.expr, state)
        state.order.append((_finish(node, state, scope, "ORDER BY", not distinct),
                            item.descending))


def _prepare(state: _State) -> None:
    """Bind every expression of the plan once the working scope is known."""
    p = state.plan
    filt = p.find(FilterStage)
    if isinstance(filt, FilterStage):
        state.where = bind(filt.predicate, state.scope, False, "WHERE")
    group = p.find(GroupStage)
    if isinstance(group, GroupStage):
        state.grouped = True
        state.keys = [bind(k, state.scope, False, "GROUP BY") for k in group.keys]
    project = p.find(ProjectStage)
    if isinstance(project, ProjectStage):
        _prepare_items(state, project.items)
    having = p.find(HavingStage)
    if isinstance(having, HavingStage):
        state.having = _finish(having.predicate, state, state.scope, "HAVING", True)
    sort = p.find(SortStage)
    if isinstance(sort, SortStage):
        _prepare_order(state, sort)
    state.prepared = True


# ---------------------------------------------------------------- stages


def _run_scan(stage: ScanStage, state: _State) -> None:
    table = _lookup_table(state, stage.table)
    state.scope = Scope([(stage.table, c.name) for c in table.columns], [stage.table])
    state.rows = table.rows


def _run_join(stage: JoinStage, state: _State) -> None:
    right = _lookup_table(state, stage.table)
    entries = state.scope.entries + [(stage.table, c.name) for c in right.columns]
    state.scope = Scope(entries, state.scope.tables + [stage.table])
    on = bind(stage.on, state.scope, False, "JOIN ... ON")
    right_rows = right.rows
    padding = [None] * len(right.columns)
    joined = []
    for left in state.rows:
        matched = False
        for row in right_rows:
            combined = left + row
            if _is_true(evaluate(on, Context(row=combined))):
                joined.append(combined)
                matched = True
        if not matched and stage.kind == "LEFT":
            joined.append(left + padding)
    state.rows = joined


def _run_filter(stage: FilterStage, state: _State) -> None:
    where = state.where
    assert where is not None
    state.rows = [r for r in state.rows if _is_true(evaluate(where, Context(row=r)))]


def _run_group(stage: GroupStage, state: _State) -> None:
    if not state.keys:
        # No GROUP BY: the whole input is one group, even when it is empty.
        state.groups = [_Group([], state.rows)]
        return
    groups: dict[tuple, _Group] = {}
    for row in state.rows:
        ctx = Context(row=row)
        values = [evaluate(k, ctx) for k in state.keys]
        key = row_key(values)
        if key in groups:
            groups[key].rows.append(row)
        else:
            groups[key] = _Group(values, [row])
    state.groups = list(groups.values())


def _compute(agg: AggCall, rows: list) -> object:
    if agg.star:
        return agg_count_star(len(rows))
    arg = agg.args[0]
    return compute_aggregate(agg.name, [evaluate(arg, Context(row=r)) for r in rows])


def _run_aggregate(stage: AggregateStage, state: _State) -> None:
    for group in state.groups:
        group.aggs = [_compute(agg, group.rows) for agg in state.aggs]


def _group_context(group: _Group) -> Context:
    return Context(keys=group.keys, aggs=group.aggs)


def _run_having(stage: HavingStage, state: _State) -> None:
    having = state.having
    assert having is not None
    state.groups = [
        g for g in state.groups if _is_true(evaluate(having, _group_context(g)))
    ]


def _run_project(stage: ProjectStage, state: _State) -> None:
    if state.grouped:
        contexts = [_group_context(g) for g in state.groups]
    else:
        contexts = [Context(row=r) for r in state.rows]
    state.outputs = [([evaluate(e, ctx) for e in state.items], ctx) for ctx in contexts]


def _run_distinct(stage: DistinctStage, state: _State) -> None:
    seen: set[tuple] = set()
    kept = []
    for out, ctx in state.outputs:
        key = row_key(out)
        if key not in seen:
            seen.add(key)
            kept.append((out, ctx))
    state.outputs = kept


def _compare_keys(a: list, b: list, descending: list[bool]) -> int:
    for x, y, desc in zip(a, b, descending):
        if x is None or y is None:
            if x is None and y is None:
                continue
            return 1 if x is None else -1  # NULL last in both directions
        if compare_eq(x, y):
            continue
        result = -1 if compare_lt(x, y) else 1
        return -result if desc else result
    return 0


def _run_sort(stage: SortStage, state: _State) -> None:
    descending = [desc for _, desc in state.order]
    decorated = []
    for out, ctx in state.outputs:
        full = Context(row=ctx.row, out=out, keys=ctx.keys, aggs=ctx.aggs)
        decorated.append(([evaluate(e, full) for e, _ in state.order], (out, ctx)))
    cmp = functools.cmp_to_key(lambda a, b: _compare_keys(a[0], b[0], descending))
    decorated.sort(key=cmp)  # list.sort is stable
    state.outputs = [pair for _, pair in decorated]


def _run_offset(stage: OffsetStage, state: _State) -> None:
    state.outputs = state.outputs[stage.count :]


def _run_limit(stage: LimitStage, state: _State) -> None:
    state.outputs = state.outputs[: stage.count]


_HANDLERS: dict[type, Callable] = {
    ScanStage: _run_scan,
    JoinStage: _run_join,
    FilterStage: _run_filter,
    GroupStage: _run_group,
    AggregateStage: _run_aggregate,
    HavingStage: _run_having,
    ProjectStage: _run_project,
    DistinctStage: _run_distinct,
    SortStage: _run_sort,
    OffsetStage: _run_offset,
    LimitStage: _run_limit,
}


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    """Run every stage of a plan and return the result."""
    state = _State(plan, tables)
    for stage in plan:
        if not state.prepared and not isinstance(stage, (ScanStage, JoinStage)):
            _prepare(state)
        handler: Callable[[Stage, _State], None] = _HANDLERS[type(stage)]
        handler(stage, state)
    return Result(list(state.columns), [list(out) for out, _ in state.outputs])


def execute(query: str, tables: dict[str, Table]) -> Result:
    """Parse, plan and execute a query."""
    return execute_plan(plan(parse(query)), tables)

